    fn a_wait_is_bounded_by_its_policy() {
        // Nothing arrives: each timeout is a policy call, and the
        // policy ends the wait.
        let mut r = Region::new();
        let mut pool = Pool::init(&mut r.0, BUF as u32, BUFS as u32).unwrap();
