#[cfg(target_os = "linux")]
pub struct Futex<const TIMEOUT_MS: u32 = 10>;

#[cfg(target_os = "linux")]
impl<const TIMEOUT_MS: u32> Wake for Futex<TIMEOUT_MS> {
    const WAKES: bool = true;

    fn wait(word: &AtomicU32, expected: u32) {
        futex_wait(
            word,
            expected,
            libc::timespec {
                tv_sec: (TIMEOUT_MS / 1000) as libc::time_t,
                tv_nsec: ((TIMEOUT_MS % 1000) * 1_000_000) as libc::c_long,
            },
        );
    }

    fn wait_for(word: &AtomicU32, expected: u32, timeout_us: u32) {
        futex_wait(
            word,
            expected,
            libc::timespec {
                tv_sec: (timeout_us / 1_000_000) as libc::time_t,
                tv_nsec: ((timeout_us % 1_000_000) * 1_000) as libc::c_long,
            },
        );
    }

    fn wake(word: &AtomicU32) {
        // SAFETY: word is a live, aligned u32, and FUTEX_WAKE only
        // wakes sleepers keyed by its address, reading nothing.
        unsafe {
            libc::syscall(
                libc::SYS_futex,
                word.as_ptr(),
                libc::FUTEX_WAKE,
                i32::MAX,
                core::ptr::null::<libc::timespec>(),
                core::ptr::null::<u32>(),
                0u32,
            );
        }
    }
}

/// One `FUTEX_WAIT` on `word` while it holds `expected`, bounded by
/// the relative `timeout`.
#[cfg(target_os = "linux")]
fn futex_wait(word: &AtomicU32, expected: u32, timeout: libc::timespec) {
    // SAFETY: word is a live, aligned u32 for the call, which the
    // kernel reads atomically against expected, and the timeout is a
    // valid relative timespec. An error return (EAGAIN when the word
    // moved, ETIMEDOUT, EINTR) is a return, and the caller looks
    // again.
    unsafe {
        libc::syscall(
            libc::SYS_futex,
            word.as_ptr(),
            libc::FUTEX_WAIT,
            expected,
            &timeout as *const libc::timespec,
            core::ptr::null::<u32>(),
            0u32,
        );
    }
}

