fn send<M: Mode, W: Wake>(prod: &MpscProducer<'_, M, W>, from: u64, to: u64) {
    for i in from..to {
        prod.send_with::<Msg>(
            |_| false,
            |m| {
                m.seq = i;
                m.val = i * 10;
            },
        )
        .unwrap();
    }
}

/// Receive `from..to` in order.
fn recv<M: Mode, W: Wake>(cons: &mut MpscConsumer<'_, M, W>, from: u64, to: u64) {
    for i in from..to {
        let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
        assert_eq!(
            *msg,
            Msg {
                seq: i,
