//! The monotonic clock the deadline sends read, as one `u64` of
//! nanoseconds.
//!
//! - On Linux: `clock_gettime(CLOCK_MONOTONIC)` through `libc`, a
//!   vDSO call with no syscall, and no `std`. It is the clock
//!   [`Futex`](crate::wake::Futex) sleeps against, so a
//!   [`Deadline`](crate::Deadline) from it is one the kernel reads.
//! - Elsewhere, with the `std` feature: `std::time::Instant`,
//!   counted from the first reading in the process.

/// Nanoseconds on the monotonic clock.
///
/// - One multiply by a constant and an add, folding the clock's
///   seconds and nanoseconds, and a `u64` of nanoseconds wraps
///   after about 584 years.
#[cfg(target_os = "linux")]
#[inline]
pub(crate) fn now_ns() -> u64 {
    let mut ts = libc::timespec {
        tv_sec: 0,
        tv_nsec: 0,
    };
    // SAFETY: ts is a live, writable timespec, and CLOCK_MONOTONIC
    // is a clock every Linux has, so the call cannot fail.
    unsafe {
        libc::clock_gettime(libc::CLOCK_MONOTONIC, &mut ts);
    }
    ts.tv_sec as u64 * 1_000_000_000 + ts.tv_nsec as u64
}

/// Nanoseconds on the monotonic clock, since the first reading in
/// the process.
#[cfg(all(not(target_os = "linux"), feature = "std"))]
pub(crate) fn now_ns() -> u64 {
    use std::sync::OnceLock;
    use std::time::Instant;
    static ORIGIN: OnceLock<Instant> = OnceLock::new();
    // u64 nanoseconds outlast any process, so the cast from u128
    // truncates nothing reachable.
    ORIGIN.get_or_init(Instant::now).elapsed().as_nanos() as u64
}
