#[derive(FromBytes, IntoBytes, KnownLayout, Immutable)]
#[repr(C)]
struct Msg {
    seq: u64,
    producer: u64,
}

/// Bytes per slot, a cache-line multiple.
const SLOT: u32 = 64;

/// Slots per segment, a power of two.
const DEPTH: u32 = 64;

