    /// assert_eq!(sent, Err(Full));
    /// assert_eq!((counting.full, counting.lost), (3, 0));
    /// ```'''
assert '    /// @SENDDOC@' in s; s=s.replace('    /// @SENDDOC@', doc,1)
open(p,'w').write(s)
